using JamunaBank.Procurement.API.Constants;using JamunaBank.Procurement.API.DTOs;using JamunaBank.Procurement.API.Models;using JamunaBank.Procurement.API.Repositories.Interfaces;using JamunaBank.Procurement.API.Services.Interfaces;
namespace JamunaBank.Procurement.API.Services.Implementations;
public sealed class WorkOrderService(IWorkOrderRepository repository,IProcurementTrackingRepository tracking,ICurrentUserService currentUser):IWorkOrderService
{
 public Task<StoredProcedureResult?>CreateAsync(CreateWorkOrderRequest r,CancellationToken c){Validate(r);return repository.CreateAsync(r,currentUser.EmployeeId,c);}
 public async Task<WorkOrderBatchResult>BulkAssignAsync(CreateWorkOrderRequest r,CancellationToken c){Validate(r);var ids=r.RequisitionIds.Distinct().ToArray();var rows=(await tracking.SearchAsync(null,null,null,null,c)).Where(x=>ids.Contains(x.RequisitionId)).ToDictionary(x=>x.RequisitionId);var eligible=ids.Where(id=>rows.TryGetValue(id,out var x)&&x.StatusCode is "READY_FOR_PROCUREMENT" or "READY_FOR_WORK_ORDER").ToArray();var results=ids.Where(id=>!eligible.Contains(id)).Select(id=>new WorkOrderAssignmentResult(id,rows.GetValueOrDefault(id)?.RequisitionNo,ResultCodes.ValidationError,rows.ContainsKey(id)?"Requisition is not ready for Work Order assignment.":"Procurement tracking was not found.")).ToList();StoredProcedureResult? created=null;if(eligible.Length>0){created=await repository.CreateAsync(new CreateWorkOrderRequest{RequisitionIds=eligible,WorkOrderNo=r.WorkOrderNo,WorkOrderDate=r.WorkOrderDate,SupplierVendor=r.SupplierVendor,ContractAgreementNo=r.ContractAgreementNo,WorkOrderValue=r.WorkOrderValue,DeliveryDate=r.DeliveryDate,Remarks=r.Remarks},currentUser.EmployeeId,c);var code=created?.ResultCode??ResultCodes.UnexpectedError;var message=created?.ResultMessage??"No stored-procedure result was returned.";results.AddRange(eligible.Select(id=>new WorkOrderAssignmentResult(id,rows[id].RequisitionNo,code,message)));}var ok=results.Count(x=>x.ResultCode==ResultCodes.Success);return new(Guid.NewGuid(),created?.EntityId,created?.ReferenceNo,ids.Length,ok,ids.Length-ok,results.OrderBy(x=>Array.IndexOf(ids,x.RequisitionId)).ToArray());}
 public Task<WorkOrderDto?>GetAsync(long id,CancellationToken c)=>repository.GetAsync(Valid(id),c);public Task<IReadOnlyList<WorkOrderDto>>GetByRequisitionAsync(long id,CancellationToken c)=>repository.GetByRequisitionAsync(Valid(id),c);private static void Validate(CreateWorkOrderRequest r){if(r.RequisitionIds is null||r.RequisitionIds.Count==0||r.RequisitionIds.Any(x=>x<=0))throw new ArgumentException("Positive requisition IDs are required.");if(string.IsNullOrWhiteSpace(r.WorkOrderNo))throw new ArgumentException("Work Order number is required.");if(r.WorkOrderDate==default)throw new ArgumentException("Work Order date is required.");if(string.IsNullOrWhiteSpace(r.SupplierVendor))throw new ArgumentException("Supplier/vendor is required.");if(r.WorkOrderValue<0)throw new ArgumentException("Work Order value cannot be negative.");if(r.DeliveryDate<r.WorkOrderDate)throw new ArgumentException("Delivery date cannot precede Work Order date.");}private static long Valid(long id){if(id<=0)throw new ArgumentOutOfRangeException(nameof(id));return id;}
}
